bool stratum_subscribe(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    long http_code;
    char *json_request;
    char *response = NULL;
    size_t response_len = 0;

    curl = curl_easy_init();
    if (!curl) {
        applog(LOG_ERR, "Failed to initialize CURL for Stratum subscription");
        return false;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1);

    // Construct JSON-RPC subscription request
    json_request = jsonrpc_call("mining.subscribe", NULL, NULL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_request);

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_HEADER, 0);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    res = curl_easy_perform(curl);
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    if (res != CURLE_OK || http_code != 200) {
        applog(LOG_ERR, "Stratum subscription failed: %s (%ld)", curl_easy_strerror(res), http_code);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(json_request);
        return false;
    }

    // Parse the JSON response for session ID and nonce
    json_t *root = json_loads(response, 0, NULL);
    if (!root || !json_is_array(root)) {
        applog(LOG_ERR, "Invalid JSON response from Stratum pool");
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(json_request);
        free(response);
        return false;
    }

    json_t *result = json_array_get(root, 0);
    if (!json_is_array(result)) {
        applog(LOG_ERR, "Subscription result not found in JSON response");
        json_decref(root);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(json_request);
        free(response);
        return false;
    }

    // Extract session ID and nonce
    const char *session_id = json_string_value(json_array_get(result, 1));
    const char *nonce = json_string_value(json_array_get(result, 2));

    if (!session_id || !nonce) {
        applog(LOG_ERR, "Failed to extract session ID and nonce from Stratum response");
        json_decref(root);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(json_request);
        free(response);
        return false;
    }

    // Update pool state
    pool->session_id = strdup(session_id);
    pool->nonce = strdup(nonce);

    applog(LOG_NOTICE, "Stratum session initiated: session_id=%s, nonce=%s", session_id, nonce);

    json_decref(root);
    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    free(json_request);
    free(response);
    return true;
}

bool initiate_stratum_session(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    long http_code;
    char *response = NULL;
    size_t response_len = 0;
    json_t *json_response;
    json_error_t error;
    const char *session_id = NULL;
    const char *nonce = NULL;

    curl = curl_easy_init();
    if (!curl) {
        applog(LOG_ERR, "Failed to initialize CURL for Stratum session");
        return false;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        applog(LOG_ERR, "Failed to set CURL headers for Stratum session");
        curl_easy_cleanup(curl);
        return false;
    }

    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"jsonrpc\": \"2.0\", \"method\": \"mining.subscribe\", \"params\": [\"client/0.1\"], \"id\": 1}");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    curl_easy_setopt(curl, CURLOPT_HEADER, 0);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    res = curl_easy_perform(curl);
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    if (res != CURLE_OK || http_code != 200) {
        applog(LOG_ERR, "Failed to connect to Stratum pool: %s", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    json_response = json_loads(response, 0, &error);
    if (!json_response) {
        applog(LOG_ERR, "Failed to parse Stratum response: %s", error.text);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    json_t *result = json_object_get(json_response, "result");
    if (!result || !json_is_array(result) || json_array_size(result) < 2) {
        applog(LOG_ERR, "Stratum response does not contain valid result array");
        json_decref(json_response);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    session_id = json_string_value(json_array_get(result, 0));
    nonce = json_string_value(json_array_get(result, 1));

    if (!session_id || !nonce) {
        applog(LOG_ERR, "Failed to extract session ID or nonce from Stratum response");
        json_decref(json_response);
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(response);
        return false;
    }

    strncpy(pool->session_id, session_id, sizeof(pool->session_id) - 1);
    strncpy(pool->nonce, nonce, sizeof(pool->nonce) - 1);

    applog(LOG_INFO, "Stratum session initiated. Session ID: %s, Nonce: %s", session_id, nonce);

    json_decref(json_response);
    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    free(response);

    return true;
}

bool stratum_subscribe(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_simples *s = NULL;
    json_t *val = NULL;
    json_error_t error;
    char *resp_str = NULL;
    bool ret = false;
    int session_id_idx = -1;
    int nonce_idx = -1;

    if (!pool || !pool->url || !pool->user)
        return false;

    if (!(curl = curl_easy_init()))
        return false;

    s = curl_simples_setup(curl, pool->url, HTTP_POST, 0);
    if (!s)
        goto out;

    if (s->headers)
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, s->headers);

    val = json_object();
    if (!val)
        goto out;

    json_object_set_new(val, "jsonrpc", json_string("2.0"));
    json_object_set_new(val, "method", json_string("mining.subscribe"));
    json_object_set_new(val, "params", json_array());
    json_object_set_new(val, "id", json_integer(1));

    s->postfields = json_dumps(val, JSON_COMPACT);
    s->postfieldsize = strlen(s->postfields);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK)
        goto out;

    resp_str = curl_easy_escape(curl, s->response, 0);
    if (!resp_str)
        goto out;

    val = json_loads(resp_str, 0, &error);
    if (!val) {
        applog(LOG_ERR, "JSON decode error on line %d: %s", error.line, error.text);
        goto out;
    }

    if (!json_object_get(val, "result")) {
        applog(LOG_ERR, "No result in JSON response");
        goto out;
    }

    json_t *result = json_object_get(val, "result");
    if (!json_is_array(result)) {
        applog(LOG_ERR, "Result is not an array");
        goto out;
    }

    if (json_array_size(result) < 2) {
        applog(LOG_ERR, "Result array too small");
        goto out;
    }

    json_t *session_id = json_array_get(result, 0);
    json_t *nonce = json_array_get(result, 1);

    if (!json_is_string(session_id) || !json_is_string(nonce)) {
        applog(LOG_ERR, "Session ID or nonce is not a string");
        goto out;
    }

    pool->session_id = strdup(json_string_value(session_id));
    pool->nonce = strdup(json_string_value(nonce));

    if (!pool->session_id || !pool->nonce) {
        applog(LOG_ERR, "Failed to duplicate session ID or nonce");
        goto out;
    }

    applog(LOG_INFO, "Stratum subscription successful. Session ID: %s, Nonce: %s", pool->session_id, pool->nonce);
    ret = true;

out:
    if (s)
        curl_simples_free(s);
    if (val)
        json_decref(val);
    if (resp_str)
        curl_free(resp_str);

    return ret;
}

