bool stratum_subscribe(struct pool *pool) {
    CURL *curl = NULL;
    CURLcode res;
    long http_code = 0;
    char *response = NULL;
    bool success = false;
    int retry_count = 0;
    const int max_retries = 3;

    if (!pool || !pool->url)
        return false;

    curl = curl_easy_init();
    if (!curl)
        return false;

    curl_easy_setopt(curl, CURLOPT_URL, pool->url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"jsonrpc\": \"2.0\", \"method\": \"mining.subscribe\", \"params\": [\"client/0.0\"]}");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    do {
        res = curl_easy_perform(curl);
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

        if (res == CURLE_OK && http_code == 200) {
            json_t *json = json_loads(response, 0, NULL);
            if (json) {
                json_t *result = json_object_get(json, "result");
                if (result && json_is_array(result)) {
                    json_t *session_id = json_array_get(result, 1);
                    json_t *nonce = json_array_get(result, 2);

                    if (session_id && json_is_string(session_id) && nonce && json_is_string(nonce)) {
                        const char *session_id_str = json_string_value(session_id);
                        const char *nonce_str = json_string_value(nonce);

                        pool->session_id = strdup(session_id_str);
                        pool->nonce = strdup(nonce_str);

                        // Log session details
                        printf("Stratum session started. Session ID: %s, Nonce: %s\n", session_id_str, nonce_str);

                        success = true;
                    }
                }

                json_decref(json);
            }
        } else {
            fprintf(stderr, "Failed to subscribe to Stratum pool. HTTP code: %ld, Error: %s\n", http_code, curl_easy_strerror(res));
            retry_count++;
            if (retry_count < max_retries) {
                sleep(1); // Wait before retry
            } else {
                break;
            }
        }
    } while (!success && retry_count < max_retries);

    curl_easy_cleanup(curl);
    free(response);
    return success;
}
